//! 🛡️ Fallible authored mapping of a genuinely received native owner, kept beside the receiving core so that crate stays within its source extent.
use semio_framework_value_native_owned::{RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetainedWorkOutcome,OriginalReceivingPrimary,ValueError,NativeDecodeControl,retirement::{RetireOwned,RetirementCursor},retained_clone::{RetainedCloneClose,RetainedCloneRef,retained_clone_grant_admits},native_decoding::{NativeReceive,NativeReceiver,owned::{NativeReceiveMap,NativeMappedReceiver,tree::{fixed,receipt,invalid}}}};
use std::mem::ManuallyDrop;
/// 🛡️ Fallible authored mapping: the received owner is validated by reference under the original control and then retired through funded closure, whether the mapping succeeds or is refused.
pub trait NativeReceiveTryMap<T>:RetireOwned+Sized{fn try_from_native(value:&T,control:&mut NativeDecodeControl<'_>)->Result<Self,ValueError>;}
struct Keep<T>(T);
impl<T:RetireOwned> RetireOwned for Keep<T>{fn retirement(self)->Box<dyn RetirementCursor>{self.0.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{self.0.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{T::controlled_retirement_supported()}}
impl<T:RetireOwned> NativeReceiveMap<T> for Keep<T>{fn from_native(value:T)->Self{Self(value)}}
/// 🛡️ Receives `T` through its genuine child receiver, then maps it fallibly into `U`; `U` is ready only after the owner `T` is retired.
pub struct NativeTryMappedReceiver<I:'static+?Sized,T:NativeReceive<I>,U:NativeReceiveTryMap<T>>{inner:NativeMappedReceiver<I,T,Keep<T>>,kept:ManuallyDrop<Option<Keep<T>>>,output:ManuallyDrop<Option<U>>,retirement:RetainedCloneClose,closing:bool}
impl<I:'static+?Sized,T:NativeReceive<I>,U:NativeReceiveTryMap<T>> NativeTryMappedReceiver<I,T,U>{pub fn new()->Self{Self{inner:NativeMappedReceiver::new(),kept:ManuallyDrop::new(None),output:ManuallyDrop::new(None),retirement:Default::default(),closing:false}}}
impl<I:'static+?Sized,T:NativeReceive<I>,U:NativeReceiveTryMap<T>>NativeReceiver<I,U>for NativeTryMappedReceiver<I,T,U>{
 fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invalid())}if self.kept.is_some()||self.output.is_some(){if self.output.is_none(){return Ok(fixed(0))}if !self.retirement.is_empty(){return self.retirement.demands(body)}return self.retirement.next_owner_demands::<Keep<T>>(true,&None,body)}if self.inner.output_ready(){return self.inner.take_demand()}self.inner.demands(input,body)}
 fn advance(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{let mut work=0;let result=(||{let d=self.demands(input,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}control.checkpoint()?;let none=RetainedCloneStep::Progress(Default::default());
  if self.kept.is_some()||self.output.is_some(){if self.output.is_none(){work=1;let kept=self.kept.as_ref().ok_or_else(||ValueError::invariant("kept absent"))?;*self.output=Some(U::try_from_native(&kept.0,control)?);return Ok(none)}let step=if self.retirement.is_empty(){let turn=self.retirement.begin_granted(&mut self.kept,g);work=turn.work;turn.result?.unwrap_or(none)}else{let turn=self.retirement.step_granted(g);work=turn.work;turn.result?};return Ok(if self.kept.is_none()&&self.retirement.is_empty(){RetainedCloneStep::Complete(step.progress())}else{RetainedCloneStep::Progress(step.progress())})}
  if self.inner.output_ready(){let turn=self.inner.take(g);work=turn.work;let Some((kept,p))=turn.result?else{return Ok(none)};*self.kept=Some(kept);return Ok(RetainedCloneStep::Progress(p))}
  let turn=self.inner.advance(input,control,body,g);work=turn.work;turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))})();RetainedWorkOutcome{result,work}}
 fn output_ready(&self)->bool{!self.closing&&self.output.is_some()&&self.kept.is_none()&&self.retirement.is_empty()}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid())}Ok(fixed(0))}
 fn take(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome<Option<(U,RetainedCloneProgress)>>{if !self.output_ready()||!retained_clone_grant_admits(g,fixed(0)){return RetainedWorkOutcome{result:Ok(None),work:0}}RetainedWorkOutcome{result:self.output.take().map(|v|Some((v,receipt(fixed(0))))).ok_or_else(||ValueError::invariant("output absent").into()),work:1}}
 fn begin_close(&mut self){self.closing=true;self.inner.begin_close();}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if !self.inner.terminal_is_empty(){return self.inner.close_demands(body)}if !self.retirement.is_empty(){return self.retirement.demands(body)}if self.kept.is_some(){return self.retirement.next_owner_demands::<Keep<T>>(true,&None,body)}if self.output.is_some(){return self.retirement.next_owner_demands::<U>(true,&None,body)}Ok(Default::default())}
 fn close_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome{let mut work=0;let result=(||{if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.inner.terminal_is_empty(){let turn=self.inner.close_step(g);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.retirement.is_empty(){let turn=self.retirement.step_granted(g);work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}let turn=if self.kept.is_some(){self.retirement.begin_granted(&mut self.kept,g)}else{self.retirement.begin_granted(&mut self.output,g)};work=turn.work;turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default())))})();RetainedWorkOutcome{result,work}}
 fn terminal_is_empty(&self)->bool{self.inner.terminal_is_empty()&&self.kept.is_none()&&self.output.is_none()&&self.retirement.is_empty()}
}
impl<I:'static+?Sized,T:NativeReceive<I>,U:NativeReceiveTryMap<T>>Drop for NativeTryMappedReceiver<I,T,U>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"native fallible mapped receiving requires funded closure");if empty{unsafe{ManuallyDrop::drop(&mut self.kept);ManuallyDrop::drop(&mut self.output);}}}}
